import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

cross_entropy_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define BLOCK_SIZE 256

__global__ void cross_entropy_kernel(
    const float* predictions,
    const int64_t* targets,
    float* loss,
    int batch_size,
    int num_classes
) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size) {
        return;
    }

    const float* preds = predictions + batch_idx * num_classes;
    int target_idx = targets[batch_idx];

    // First pass: find max for numerical stability
    float max_val = -INFINITY;
    for (int c = 0; c < num_classes; c++) {
        max_val = fmaxf(max_val, preds[c]);
    }

    // Second pass: compute sum of exp and the target contribution
    float sum_exp = 0.0f;
    float target_pred = preds[target_idx];

    for (int c = 0; c < num_classes; c++) {
        sum_exp += expf(preds[c] - max_val);
    }

    // Compute log-sum-exp: max + log(sum(exp(x - max)))
    float log_sum_exp = max_val + logf(sum_exp);

    // Cross entropy for this sample: -target_pred + log_sum_exp
    loss[batch_idx] = -target_pred + log_sum_exp;
}

__global__ void reduce_mean_kernel(
    const float* per_sample_losses,
    float* mean_loss,
    int batch_size
) {
    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    // Load data into shared memory
    sdata[tid] = (i < batch_size) ? per_sample_losses[i] : 0.0f;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Write block result
    if (tid == 0) {
        atomicAdd(mean_loss, sdata[0] / (float)batch_size);
    }
}

torch::Tensor cross_entropy_hip(torch::Tensor predictions, torch::Tensor targets) {
    int batch_size = predictions.size(0);
    int num_classes = predictions.size(1);

    // Compute per-sample losses
    auto per_sample_losses = torch::zeros({batch_size}, predictions.options());

    const int block_size = BLOCK_SIZE;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    cross_entropy_kernel<<<num_blocks, block_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<int64_t>(),
        per_sample_losses.data_ptr<float>(),
        batch_size,
        num_classes
    );

    // Reduce to mean loss
    auto mean_loss = torch::zeros({1}, predictions.options());

    // Use fewer blocks for reduction
    int reduce_blocks = (batch_size + block_size - 1) / block_size;
    reduce_mean_kernel<<<reduce_blocks, block_size, block_size * sizeof(float)>>>(
        per_sample_losses.data_ptr<float>(),
        mean_loss.data_ptr<float>(),
        batch_size
    );

    return mean_loss;
}
"""

