    cross_entropy_kernel<<<num_blocks, threads_per_block>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<int64_t>(),
        block_losses.data_ptr<float>(),
        batch_size,
        num_classes
    );

    auto mean_loss = torch::zeros({1}, predictions.options());
    reduce_mean_kernel<<<1, 256, 256 * sizeof(float)>>>(
        block_losses.data_ptr<float>(),
        mean_loss.data_ptr<float>(),
        batch_size
    );

    return mean_loss;
}
