__global__ void cross_entropy_kernel(
    const float* __restrict__ predictions,
    const int64_t* __restrict__ targets,
    float* __restrict__ losses,
    int batch_size,
    int num_classes
) {
    int block_samples_base = blockIdx.x * SAMPLES_PER_BLOCK;
    int sample_idx_in_block = threadIdx.x % SAMPLES_PER_BLOCK;
    int warps_per_sample = blockDim.x / SAMPLES_PER_BLOCK / 32;
    int warp_id = threadIdx.x / 32;
    int sample_warp_id = warp_id % warps_per_sample;
    int lane_id = threadIdx.x % 32;

    int sample_idx = block_samples_base + sample_idx_in_block;

    __shared__ float sample_data[SAMPLES_PER_BLOCK][2];  // [max_val, sum_exp]
    __shared__ int sample_targets[SAMPLES_PER_BLOCK];
    __shared__ float sample_preds[SAMPLES_PER_BLOCK];

    // Initialize shared memory
    if (lane_id < 2) {
        sample_data[sample_idx_in_block][lane_id] = (lane_id == 0) ? -INFINITY : 0.0f;
    }
    if (lane_id == 0) {
        if (sample_idx < batch_size) {
            sample_targets[sample_idx_in_block] = targets[sample_idx];
            const float* preds = predictions + sample_idx * num_classes;
            sample_preds[sample_idx_in_block] = preds[sample_targets[sample_idx_in_block]];
        } else {
            sample_preds[sample_idx_in_block] = 0.0f;
        }
    }
    __syncthreads();

    if (sample_idx >= batch_size) {
        if (sample_idx_in_block == 0 && lane_id == 0) {
            losses[blockIdx.x] = 0.0f;
        }
        return;
    }

    const float* preds = predictions + sample_idx * num_classes;

    // Warp-level reduction of max
    float max_val = -INFINITY;
    for (int c = sample_warp_id * 32 + lane_id; c < num_classes; c += warps_per_sample * 32) {
        max_val = fmaxf(max_val, preds[c]);
    }
    max_val = warp_reduce_max(max_val);

    // Store max for the sample
    if (lane_id == 0) {
        atomicMax(&sample_data[sample_idx_in_block][0], max_val);
    }
    __syncthreads();

    max_val = sample_data[sample_idx_in_block][0];

    // Warp-level reduction of sum_exp
    float sum_exp = 0.0f;
    for (int c = sample_warp_id * 32 + lane_id; c < num_classes; c += warps_per_sample * 32) {
        sum_exp += expf(preds[c] - max_val);
    }
    sum_exp = warp_reduce_sum(sum_exp);

    // Store sum for the sample
    if (lane_id == 0) {
        atomicAdd(&sample_data[sample_idx_in_block][1], sum_exp);
    }
    __syncthreads();

    sum_exp = sample_data[sample_idx_in_block][1];

    // Write result
    if (sample_idx_in_block == 0 && lane_id == 0) {
        float block_loss = 0.0f;
        for (int i = 0; i < SAMPLES_PER_BLOCK; i++) {
            if (block_samples_base + i < batch_size) {
                float s_max = sample_data[i][0];
                float s_sum = sample_data[i][1];
                float s_pred = sample_preds[i];
                block_loss += (-s_pred + s_max + logf(s_sum));
            }
        }
        losses[blockIdx.x] = block_loss;
    }
